            outfile = context.CLIARGS['output_file']
            if outfile is None:
                # FIXME: pager?
                display.display(results)
            else:
                with open(to_bytes(outfile), 'wb') as f:
                        f.write(to_bytes(results))
            sys.exit(0)

        sys.exit(1)

